import { ethers } from 'ethers'
import * as contractArtifacts from '../abi-configs'
import * as abis from '../interfaces/abi-v2'
import { Console } from './console'

export const getContractArtifact = (name: string) => {
  // sdk return getContractArtifact
  if (contractArtifacts.getContractArtifact) {
    return contractArtifacts.getContractArtifact(name)
  }
  const pathFunc = contractArtifacts[name]
  if (typeof pathFunc !== 'string') {
    // pathFunc return require(pathFunc)
    return pathFunc
  } else {
    try {
      // pathFunc is path url
      return require(pathFunc)
    } catch {
      throw new Error(`Unable to getContractArtifact for contract: ${name}`)
    }
  }
}

/**
 * Gets the hardhat artifact for the given contract name.
 * Will throw an error if the contract artifact is not found.
 *
 * @param name Contract name.
 * @returns The artifact for the given contract name.
 */
export const getContractDefinition = (name: string, path?: string): any => {
  // We import this using `require` because hardhat tries to build this file when compiling
  // the contracts, but we need the contracts to be compiled before the contract-artifacts.ts
  // file can be generated.
  // eslint-disable-next-line @typescript-eslint/no-var-requires
  let artifact = getContractArtifact(name)
  // v2 !artifact || isV2
  // Console.log('getContractDefinition abis', name, abis[name])

  if (!artifact) artifact = { abi: abis[name] }

  if (artifact === undefined) {
    throw new Error(`Unable to find artifact for contract: ${name}`)
  }
  return artifact
}

/**
 * Gets an ethers Interface instance for the given contract name.
 *
 * @param name Contract name.
 * @returns The interface for the given contract name.
 */
export const getContractInterface = (
  name: string,
  path?: string
): ethers.utils.Interface => {
  const definition = getContractDefinition(name, path)
  return new ethers.utils.Interface(definition.abi || definition)
}
